AUDIT (
  name inventory_level_conservation
);

WITH _survivors AS (
  SELECT
    TRY_CAST(day AS DATE) AS stock_date,
    TRY_CAST(on_hand AS BIGINT) AS stock_level,
    TRY_CAST(warehouse AS TEXT) AS warehouse_id,
    _ingested_at,
    _load_id,
    _source_row_id,
    TRY_CAST(day AS DATE) IS NULL AND (
      NOT day IS NULL
    ) AS _branch_stock_date_coercible,
    TRY_CAST(on_hand AS BIGINT) IS NULL AND (
      NOT on_hand IS NULL
    ) AS _branch_stock_level_coercible,
    TRY_CAST(warehouse AS TEXT) IS NULL AND (
      NOT warehouse IS NULL
    ) AS _branch_warehouse_id_coercible
  FROM bronze.wms__stock_levels
  QUALIFY
    ROW_NUMBER() OVER (
      PARTITION BY warehouse_id, stock_date
      ORDER BY _ingested_at DESC, _load_id DESC, _source_row_id DESC
    ) = 1
)
SELECT
  *
FROM (
  SELECT
    COUNT(*) AS surviving_rows,
    SUM(
      CASE
        WHEN COALESCE(
          (
            _survivors._branch_stock_date_coercible
            OR _survivors._branch_stock_level_coercible
            OR _survivors._branch_warehouse_id_coercible
            OR _survivors.stock_level < 0
          ),
          FALSE
        )
        THEN 1
        ELSE 0
      END
    ) AS diverted_rows,
    (
      SELECT
        COUNT(*)
      FROM bronze.wms__stock_levels
    ) AS bronze_rows,
    (
      SELECT
        COUNT(*)
      FROM @this_model AS _entity
      WHERE
        _entity._source_row_id IN (
